output.result.ask"]}},{"name":"qd4_destination","description":"Arranges where the results go. Call it with the channel the caller named (channelSaid: fax, email, the other fax, a number not on file, or their EHR; empty to learn what is on file) and any email address they said (emailSaid). Returns status ASK_CHANNEL, FAX_OFFER, NO_FAX, ASK_EMAIL, NO_EMAIL, EMAIL_MATCH, EMAIL_MISS, EMAIL_MISS_FINAL, ONLY_ON_FILE, EHR or NO_DESTINATION with say (the words to use) and ask (what to ask next).","parameters":[{"name":"channelSaid","type":"string","required":false,"description":"The channel or destination the caller named, in their words; empty to learn what is on file."},{"name":"emailSaid","type":"string","required":false,"description":"The email address exactly as the caller said it, with at and dot; empty otherwise."},{"name":"acct8","type":"string","required":false,"description":"The authenticated account number, supplied automatically.","defaultSource":"runtime","visibility":{"model":false}},{"name":"buildingNumber","type":"string","required":false,"description":"The account building number, supplied automatically.","defaultSource":"runtime","visibility":{"model":false}},{"name":"policy","type":"object","required":false,"description":"The POLICY block, supplied automatically.","properties":[{"name":"type","type":"string","required":false},{"name":"description","type":"string","required":false}],"defaultSource":"runtime","visibility":{"model":false}},{"name":"dheld","type":"object","required":false,"description":"The delivery state held so far, supplied automatically.","properties":[{"name":"type","type":"string","required":false},{"name":"description","type":"string","required":false}],"defaultSource":"runtime","visibility":{"model":false}},{"name":"acctRef","type":"string","required":false,"description":"A reference to the authenticated account, supplied automatically.","defaultSource":"runtime","visibility":{"model":false}}],"returns":{"type":"object"},"hints":{"cac