git account number."},{"name":"buildingNumber","type":"string","required":false,"description":"The account location building number."},{"name":"patientId","type":"string","required":true,"description":"The patient id from the lookup record."},{"name":"testName","type":"string","required":false,"description":"The test name of the selected accession."},{"name":"status","type":"string","required":true,"description":"queued for a ready result, scheduled for a pending one."}],"returns":{"type":"object"},"hints":{"cacheable":false,"latency":"medium","parallelizable":true,"side_effects":true,"requires_auth":false},"provenance":{"source":"project"},"tool_type":"http","http_binding":{"endpoint":"{{env.QD_API_BASE_URL}}/deliveries","method":"POST","auth":{"type":"none"},"idempotency_header":"Idempotency-Key","headers":{"Content-Type":"application/json"}},"variable_namespace_ids":["01a17931-470a-72cd-89b1-a0b3ad60a2db"],"effect":"side_effect","confirmation":{"require":"never","immutable_params":["destination","accession","accountNumber"]},"pii_access":"tools","model_context":{"fields":["id","status"]}},{"name":"qd4_case","description":"Builds and writes the Case record for the call state and event. Returns status OK with the Case id, outcome and requests.","parameters":[{"name":"state","type":"object","required":true,"description":"The call state: session_id, account, caller_*, requests[], current_request, transfer_reason, policy, timestamps, metrics.","properties":[{"name":"type","type":"string","required":false},{"name":"description","type":"string","required":false}]},{"name":"event","type":"string","required":true,"description":"in_progress, delivered, pending, transfer, abandoned or no_action."},{"name":"caseId","type":"string","required":false,"description":"The Case id to update; empty to create the write-ahead record."}],"returns":{"type":"object"},"hints":{"cacheable":false,"latency":"medium","parallelizable":true,"side_effects":true,"requires_auth":false},"provenance